// Shared-mmap allocation for andesim.
//
// The hybrid handoff needs a file-backed mmap both legs share, so QEMU1's guest
// memory survives into the vsim leg. This minimal slice backs it with a plain
// /dev/shm sparse file (mkstemp + truncate); the tiered backing-store resolver
// and the guest --mem-size plumbing land as the feature grows.
#ifndef ANDESIM_SHM_HPP
#define ANDESIM_SHM_HPP

#include <string>

namespace andes_sim {

// Allocate a sparse mmap file of `size` bytes under /dev/shm (mkstemp +
// truncate), print one "[hsim mmap] <size> bytes at <dir>" line, and return its
// path. On failure returns "" and sets `err`. The caller owns the file and must
// unlink it when done.
std::string allocate(long long size, std::string& err,
                     const std::string& prefix = "hsim-shm.");

}  // namespace andes_sim

#endif  // ANDESIM_SHM_HPP
