// `andesim run --mode fast|cycle|hybrid [engine selection] ELF [-- engine args]`.
//
// The top selection axis. F7/F8 land the two standalone models, `fast` (QEMU)
// and `cycle` (a cycle-accurate engine, from reset): each resolves its engine,
// then hands off to transparent passthrough -- the ELF plus everything after
// `--` becomes the engine's own command line, run with inherited stdio, no
// timeout, and the exit code propagated, so a gdbstub / monitor / semihosting
// console all behave as if the engine were invoked directly. `hybrid` (F9)
// orchestrates a QEMU1 -> vsim handoff via run_plan and prints the window-cycle
// figure (the vsim mcycle delta), delimited by the marker or pc trigger.
#include <cstdio>
#include <filesystem>
#include <string>
#include <vector>

#include "cli.hpp"
#include "engine_registry.hpp"
#include "hybrid.hpp"
#include "models.hpp"
#include "plan.hpp"
#include "process.hpp"
#include "run_passthrough.hpp"
#include "run_plan.hpp"

namespace fs = std::filesystem;

namespace andes_sim {
namespace {

// Validate the lone-ELF positional shape the standalone models require: print
// the diagnostic and return 2 on a violation, else 0. `model` labels the error.
int check_one_elf(const Cli& cli, const char* model) {
  if (cli.positional.empty()) {
    std::fprintf(stderr,
                 "andesim run --mode %s: missing ELF (the workload to run; "
                 "e.g. a tests/fixtures/<name>.elf)\n",
                 model);
    return 2;
  }
  if (cli.positional.size() > 1) {
    std::fprintf(stderr,
                 "andesim run --mode %s: unexpected argument '%s' "
                 "(engine args go after --)\n",
                 model, cli.positional[1].c_str());
    return 2;
  }
  return 0;
}

// The standalone spine shared by `fast` and `cycle`: both take a single ELF,
// then run the resolved engine standalone with the post-`--` args forwarded
// verbatim, inheriting stdio (an interactive gdbstub / monitor / semihosting
// console works unchanged) and propagating the exit code. The per-model engine
// + selection are resolved by the caller; `model` here only labels the
// positional diagnostics. This minimal slice does no ELF existence/arch
// validation (that lands with strict validation).
int run_standalone(const Cli& cli, const EngineDescriptor& eng,
                   const char* model) {
  if (int rc = check_one_elf(cli, model)) return rc;
  std::string err;
  const std::vector<std::string> argv = passthrough_argv(
      eng, "standalone", cli.positional[0], cli.passthrough, err);
  if (!err.empty()) {
    std::fprintf(stderr, "andesim run: %s\n", err.c_str());
    return 2;
  }
  return exec_passthrough(argv);
}

// `run --mode fast`: QEMU alone, functional, transparent passthrough. Resolves
// the built-in qemu descriptor directly (no engine discovery -- fast needs only
// qemu, and discover_engines would spawn a --describe per Verilator build).
int run_fast(const Cli& cli) {
  // fast is QEMU-only; an explicit engine must name it.
  if (!cli.engine.empty() && cli.engine != "qemu") {
    std::fprintf(stderr,
                 "andesim run --mode fast: engine must be 'qemu', got '%s'\n",
                 cli.engine.c_str());
    return 2;
  }
  return run_standalone(cli, builtin_qemu(), "fast");
}

// `run --mode cycle`: one cycle-accurate engine alone, from reset (no QEMU,
// no --resume-from-qemu), transparent passthrough -- cycles surface in the
// engine's own output. Unlike fast, this must discover the Verilator build(s)
// to resolve the engine (explicit --engine, else the sole one).
int run_accurate(const Cli& cli) {
  Discovery disc = discover_engines();
  std::string err;
  const EngineDescriptor* eng =
      resolve_accurate_engine(disc.engines, cli.engine, err);
  if (!eng) {
    std::fprintf(stderr, "andesim run --mode cycle: %s\n", err.c_str());
    // Surface why an expected engine may be absent (failed --describe, etc.).
    for (const std::string& w : disc.warnings)
      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
    return 2;
  }
  return run_standalone(cli, *eng, "cycle");
}

// `run --mode hybrid`: orchestrate a QEMU1 fast-forward -> vsim measure+drain
// handoff (no QEMU2). The trigger (marker|pc) delimits the ROI; the cycle figure
// is the vsim mcycle minus QEMU1's drained mcycle. This slice builds the 2-step
// plan and runs it; the exact per-leg dry-run command lines, --mem-size, and
// --verify land as the feature grows.
int run_hybrid(const Cli& cli) {
  auto fail = [](const std::string& msg) {
    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", msg.c_str());
    return 2;
  };

  if (int rc = check_one_elf(cli, "hybrid")) return rc;
  const std::string elf = cli.positional[0];

  std::string err;
  const Trigger trig = hybrid_trigger(cli, elf, err);
  if (!err.empty()) return fail(err);

  // qemu is the built-in fast leg; resolve the accurate (vsim) leg by --engine
  // or the sole cycle-accurate engine (reusing the F8 selector).
  Discovery disc = discover_engines();
  const EngineDescriptor* acc =
      resolve_accurate_engine(disc.engines, cli.engine, err);
  if (!acc) {
    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", err.c_str());
    for (const std::string& w : disc.warnings)
      std::fprintf(stderr, "andesim: skipped engine: %s\n", w.c_str());
    return 2;
  }

  Plan plan;
  plan.elf = elf;
  plan.mem_size = 128LL * 1024 * 1024;  // shared mmap; --mem-size lands later
  plan.steps = {
      Step{"qemu", "fast-leg", trig},
      Step{acc->id, "accurate-leg", trig},
  };

  // Banner to stderr so the window-cycle result stands alone on stdout.
  const std::string fixture = fs::path(elf).stem().string();
  std::fprintf(stderr, "[andesim] model=hybrid engine=%s trigger=%s fixture=%s\n",
               acc->id.c_str(), trig.kind.c_str(), fixture.c_str());

  // --dry-run: report the 2-step plan and spawn nothing. The exact per-leg
  // command lines land with the dry-run print feature; here we confirm the
  // plan the handoff would run.
  if (cli.dry_run) {
    std::printf("[andesim] dry-run: %zu-step plan (spawns nothing)\n",
                plan.steps.size());
    for (size_t i = 0; i < plan.steps.size(); ++i)
      std::printf("# step %zu/%zu: %s [%s]\n", i + 1, plan.steps.size(),
                  plan.steps[i].role.c_str(), plan.steps[i].engine_id.c_str());
    return 0;
  }

  const PlanResult r = run_plan(plan, disc.engines);
  if (!r.ok()) {
    std::fprintf(stderr, "andesim run --mode hybrid: %s\n", r.error.c_str());
    return 1;
  }
  // phases[0] = QEMU1 drain, [1] = vsim drain; the window figure is the vsim
  // mcycle delta.
  const unsigned long long q_mc = r.phases[0].mcycle;
  const unsigned long long v_mc = r.phases[1].mcycle;
  std::printf("[%s window_cycles] %llu  (vsim mcycle=%llu - qemu mcycle=%llu)\n",
              trig.kind.c_str(), v_mc - q_mc, v_mc, q_mc);
  std::printf("PASS: --mode hybrid --trigger %s (%s)\n", trig.kind.c_str(),
              fixture.c_str());
  return 0;
}

}  // namespace

int cmd_run(const Cli& cli) {
  if (cli.model.empty()) {
    std::fprintf(stderr,
                 "andesim run: --mode fast|cycle|hybrid is required "
                 "(pick the composition; see 'andesim run --help')\n");
    return 2;
  }
  if (!find_model(cli.model)) {
    std::fprintf(stderr,
                 "andesim run: unknown model '%s' (want fast|cycle|hybrid)\n",
                 cli.model.c_str());
    return 2;
  }
  if (cli.model == "fast") return run_fast(cli);
  if (cli.model == "cycle") return run_accurate(cli);
  return run_hybrid(cli);  // model validated above; only hybrid remains
}

}  // namespace andes_sim

